SELECT primary_key as contractCode, source, contract_name, contract_number,unity_no_config,display_contract_number,contract_type, buyer, buyer_name,seller, customer_code, enterprise_code as ownedEnterpriseCode, user_code, user_name, language, payment_strategy,product_grade, column_titles, amount_title, product_detail, state,contract_time, data_version,purchase_contract,sell_quotation,buyer_quotation,signed_contract,cancel_reason,sell_order,order_return_reason,son_enterprise_code, money_apply_returned,invoice_apply_returned,pre_ordered, delete_flag,business_belong, qrcode_generated_flag FROM ${tableName} WHERE enterprise_code= #{enterpriseCode} AND delete_flag= 'f'
AND state IN
#{state}
AND user_code IN
#{userCode}
AND (contract_number LIKE '%'|| #{contractNumber}||'%' or display_contract_number LIKE '%'|| #{contractNumber}||'%')
AND buyer_name LIKE '%'|| #{buyerName} ||'%'
AND contract_time >= #{contractTimePreDate}
AND contract_time <= #{contractTimePostDate}
AND (money_apply_returned = true OR invoice_apply_returned = true)
AND COALESCE(money_apply_returned, false) = false AND COALESCE(invoice_apply_returned, false) = false
${dataScopeParams.dataScope}
AND business_belong = #{businessBelong}
ORDER BY id DESC

SELECT COALESCE(SUM(
        COALESCE((product_detail::json->>'productAmount')::numeric, 0)
        *
        COALESCE((payment_strategy::json->>'exchangeRate2RMB')::numeric, 1)
    ), 0)
FROM ${tableName}
WHERE enterprise_code = #{enterpriseCode}
  AND delete_flag = 'f'
  AND state IN ('MUTUAL_SIGN', 'UNILATERAL_SIGN', 'SEALED')
  AND contract_time IS NOT NULL
  AND contract_time >= #{startDate}
  AND contract_time <= #{endDate}

    ${dataScopeParams.dataScope}

SELECT customer_code AS customerCode,
       COUNT(1)      AS contractCount
FROM ${tableName}
WHERE enterprise_code = #{enterpriseCode}
  AND delete_flag = 'f'
  AND customer_code IS NOT NULL

    ${dataScopeParams.dataScope}

GROUP BY customer_code

